(6126435, 902194, 114225, '<td valign="top">Love the perspective you used here. that and the tilt adds a sense of goofiness to the photo.</td>', 'Love the perspective you used here. that and the tilt adds a sense of goofiness to the photo.', '2010-08-10 21:27:38.000000', NULL, 1),
(6126436, 902348, 114225, '<td valign="top">Wonderful catch. I love the composition with the adult just entering the frame. Great colors and details.</td>', 'Wonderful catch. I love the composition with the adult just entering the frame. Great colors and details.', '2010-08-10 21:28:58.000000', NULL, 1),
(6126437, 902214, 114225, '<td valign="top">Wow! Some fantastic textures in the skin and eye. Great photo.</td>', 'Wow! Some fantastic textures in the skin and eye. Great photo.', '2010-08-10 21:30:35.000000', NULL, 1),
(6126440, 902182, 114225, '<td valign="top">Nice composition. The duo-tone effect gives a sense of timelessness.<br/>However, I don''t like all of the blown out highlights.</td>', 'Nice composition. The duo-tone effect gives a sense of timelessness.However, I don''t like all of the blown out highlights.', '2010-08-10 21:32:30.000000', NULL, 1),
(6126448, 902513, 114225, '<td valign="top">Cute setup. This doesn''t really fit the spirit of the challenge, IMHO. But the real downside to this photo is the eyes. Reminds me of "Village of the Damned," which isn''t a good thing!</td>', 'Cute setup. This doesn''t really fit the spirit of the challenge, IMHO. But the real downside to this photo is the eyes. Reminds me of "Village of the Damned," which isn''t a good thing!', '2010-08-10 21:36:00.000000', NULL, 1),
